add('figure-01',2,[612,82,1094,619],'Freshly hydrogen-terminated Si(100) surface','Noncontact AFM image of a freshly etched substrate with monatomic steps.','Etched Si(100) substrate before silver deposition; no Ag nanoparticles assigned.',notes=['Original field 3 µm × 3 µm; reported mean step height 1.3 ± 0.4 Å.','These steps are substrate topography, not silver particle size or a refined atomic structure.'])
add('figure-02',3,[102,82,582,963],'Doping-dependent cyclic voltammetry','Four cyclic-voltammetry panels at 20 mV/s compare silver-free and silver-containing electrolytes and two substrate doping levels.','Panels a/b: n++-Si, c: n-Si; panel d is n-Si in discussion but n++-Si in caption.',panels=['a: silver-free 0.1 M LiClO4/MeCN on n++-Si','b: Ag-containing electrolyte on n++-Si','c: silver-free electrolyte on n-Si','d: Ag-containing electrolyte; doping label conflict'],notes=['Figure caption gives 10.0 mM AgClO4 in b/d; body says 1.0 mM for b. Preserve conflict and do not replace the separate 1 mM plating method.','Axis says Potential, V while tick labels are −800…800 and discussion uses mV; keep original pixels and identify unit inconsistency.','Sequential scans are not separate synthesis recipes.'])
add('scheme-01',4,[102,80,580,663],'Source energy-band interpretation','Six energy diagrams compare degenerate and nondegenerate Si at open, negative and positive polarization.','Authors’ explanatory band model for the two Si doping classes; band edges not experimentally determined here.',kind='scheme',evidence='source_theoretical_schematic',panels=['a–c: n++-Si(100)','d–f: n-Si(100)'],notes=['Shown 1.0 mM Ag+ and approximately 600 meV barrier are model context, not experimentally refined bands.','No measured depletion-layer geometry, atomic interface or particle arrangement is supplied.'])
